import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office — quote", () => {
  // Simplest case
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
  });

  // Base premiums for main items (newcomer: 0 years, first quote → +10% first insurance)
  it("a single sword (base 100 G) for a newcomer → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("a single amulet (base 60 G) for a newcomer → premium 71 G (60 + 6 + 5)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("a single staff (base 80 G) for a newcomer → premium 93 G (80 + 8 + 5)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
  });
  it.todo("a single potion (base 40 G) for a newcomer → premium 49 G (40 + 4 + 5)");

  // Components and the building block
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // Item-specific modifiers
  it.todo("a cursed sword adds a 50 % surcharge on the sword's base premium (100 → 150 G base)");
  it.todo("a sword with exactly enchantment 5 adds a 30 % high-enchantment surcharge (100 → 130 G base)");
  it.todo("a sword with enchantment 4 gets no high-enchantment surcharge (100 G base)");
  it.todo("a cursed sword with exactly enchantment 5 gets both surcharges (100 + 50 + 30 = 180 G base)");

  // Modifier scope on multi-item policies
  it.todo("a cursed sword (100 G) and a plain amulet (60 G) → 210 G before further modifiers and fee (curse adds 50 G, 50 % of the sword only)");

  // Policy-wide modifiers
  it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("every quote carries the 10 % first-insurance surcharge on the policy base premium");
  it.todo("the second quote in a scenario receives the 15 % follow-up-contract discount");
  it.todo("the first quote in a scenario receives no follow-up-contract discount");
  it.todo("the processing fee of 5 G is added at the very end, after all percentage modifiers");

  // Rounding
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up in MHPCO's favor)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // Integration examples
  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
});

describe("MHPCO Claim Office — insurance sum and cap", () => {
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)");
  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (based on the unmodified insurance value)");
});

describe("MHPCO Claim Office — claim", () => {
  // Standard reimbursement
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible)");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (no enchantment level or material, so no special clause)");

  // Deductible per damage event
  it.todo("a dragon attack damaging an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // Enchantment threshold vs. dragon material
  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G (50 % clause, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (both clauses apply; the 50 % rule wins, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (only the dragon-material clause: full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (only the high-enchantment clause: 50 % first, then deductible)");

  // Cap exhaustion across successive claims
  it.todo("a sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("a sword policy (cap 2000 G), second claim of 1500 G after the first → payout 600 G, remainingCap 0 G");

  // Multiple items of the same type
  it.todo("a policy covering two swords, a dragon attack damaging both → each damage entry gets its own deductible");

  // Rounding
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down in MHPCO's favor)");
});

describe("MHPCO Claim Office — errors", () => {
  it.todo("a quote with an item of an unknown type (e.g. broomstick) → error");
  it.todo("a claim damaging an amulet when only a sword is insured → error");
  it.todo("a claim damaging an item of an unknown type → error");
  it.todo("a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
  it.todo("a claim with a damage entry of amount -200 → error");
});

describe("MHPCO Claim Office — CLI", () => {
  it.todo("reads a JSON scenario from stdin and writes {results: [...]} to stdout with one result per step");
  it.todo("the schema example (amulet quote + amulet claim, 5-year customer) produces a premium result and a payout/remainingCap result");
  it.todo("exits with a non-zero status code and writes an error description to stderr on an unknown item type, with no results on stdout");
  it.todo("exits with a non-zero status code and writes an error description to stderr on an invalid claim");
});

