export type QuoteResult = { premium: number };

export type ScenarioResults = { results: QuoteResult[] };

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const ITEM_BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

type Item = { type: string };

type Step = { op: string; items: Item[] };

type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

const BLOCK_SIZE = 3;

// Forced so far only by a policy that is nothing but one rune block, so this is
// the premium of the whole policy, not yet of a block within a larger policy.
const THREE_RUNE_BLOCK_BASE_PREMIUM = 60;

const isThreeRuneBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");

const policyBasePremium = (items: Item[]): number => {
  if (isThreeRuneBlock(items)) return THREE_RUNE_BLOCK_BASE_PREMIUM;

  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
};

const quoteStep = (step: Step): QuoteResult => {
  const basePremium = policyBasePremium(step.items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return {
    premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  };
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(quoteStep),
});

