export type QuoteResult = { premium: number };

export type ScenarioResults = { results: QuoteResult[] };

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const ITEM_BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

type Item = { type: string };

type Step = { op: string; items: Item[] };

type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

const BLOCK_SIZE = 3;

// A block is exactly BLOCK_SIZE items of the same type; 4 runes are not a
// block, and 2 runes + 1 moonstone is not a block. Every block the tests pin
// down so far is a rune block priced at 60, and always as the whole policy —
// hence the single constant rather than a per-type block price, and the
// whole-policy check rather than a search for blocks within a larger list.
const BLOCK_BASE_PREMIUM = 60;

const isWholePolicyBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE &&
  items.every((item) => item.type === items[0].type);

const policyBasePremium = (items: Item[]): number => {
  if (isWholePolicyBlock(items)) return BLOCK_BASE_PREMIUM;

  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
};

const quoteStep = (step: Step): QuoteResult => {
  const basePremium = policyBasePremium(step.items);
  // Deliberately additive, not `base * (1 + rate)`: the latter is the same in
  // exact arithmetic but not in binary floating point (100 * 1.1 is
  // 110.00000000000001), and Math.ceil turns that 1e-14 into a whole gold piece.
  const afterPercentageModifiers =
    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  // The fee is added after every percentage modifier, and only the final
  // premium is rounded — intermediates stay fractional.
  return { premium: Math.ceil(afterPercentageModifiers + PROCESSING_FEE) };
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(quoteStep),
});

