const DEDUCTIBLE_PER_DAMAGE = 100;

const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

// The insurance sum is the plain sum of the items' insurance values; the block
// discount applies to the premium only, never to the sum insured.
const insuranceSum = (items: Item[]): number =>
  sum(items.map((item) => ITEM_INSURANCE_VALUE[item.type]));

const damagePayout = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

const claimStep = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
  const cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(policyItems);
  // The deductible applies once per damaged item, so each damage entry is
  // reduced separately before the entries are summed.
  const payout = Math.floor(sum(step.incident.damages.map(damagePayout)));

  return { payout, remainingCap: cap - payout };
};

const runStep = (
  step: StepInput,
  customer: Customer,
  precedingSteps: StepInput[],
): StepResult => {
  if (isQuoteStep(step)) {
    return quoteStep(step, customer, isFollowUpContract(precedingSteps));
