const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;

const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

const isBarelyReimbursable = (item: Item): boolean =>
  (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD;

// The reimbursement clause applies to the damage amount first; the deductible
// comes off whatever the clause leaves.
const damagePayout = (damage: Damage, item: Item): number => {
  const reimbursed = isBarelyReimbursable(item)
    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : damage.amount;

  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
};

// The deductible applies once per damaged item, so each damage entry is
// reduced separately before the entries are summed. A damage entry names the
// insured item by type, so the clauses are read off the policy's own item.
const incidentPayout = (incident: Incident, policyItems: Item[]): number =>
  Math.floor(
    sum(
      incident.damages.map((damage) => {
        const item = policyItems.find(
          (candidate) => candidate.type === damage.itemType,
        );
        if (item === undefined) {
          throw new Error(
            `Damaged item is not part of the policy: ${damage.itemType}`,
          );
        }
        return damagePayout(damage, item);
      }),
    ),
  );

