const settleClaim = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
  const payout = incidentPayout(step.incident, policyItems);

  return { payout, remainingCap: policyCap(policyItems) - payout };
};

const quoteStepAt = (steps: StepInput[], index: number): QuoteStep => {
  // `policy` is a step number in the scenario, so it indexes the full step
  // list — not a prefix of it.
  const step = steps[index];
  if (step === undefined || !isQuoteStep(step)) {
    throw new Error(`Claim references a step that is not a quote`);
  }
  return step;
};

const runStep = (
  step: StepInput,
  customer: Customer,
  steps: StepInput[],
  index: number,
): StepResult => {
  if (isQuoteStep(step)) {
    return priceQuote(step, customer, isFollowUpContract(steps, index));
  }
  if (isClaimStep(step)) {
    return settleClaim(step, quoteStepAt(steps, step.policy).items);
  }
  throw new Error(`Unsupported step op: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step, index) =>
    runStep(step, scenario.customer, scenario.steps, index),
  ),
});

